sql.where:
t.user_id = #{userId} AND t.deleted_at IS NULL
AND t.status = #{status}
AND t.project_id IS NULL
AND t.project_id = #{projectId}
AND t.priority = #{priority}
AND t.due_at < #{now} AND t.status = 'PENDING'
AND t.due_at >= #{todayStart} AND t.due_at < #{tomorrowStart}
AND t.due_at >= #{tomorrowStart}
AND t.due_at IS NULL

mapper.update:
UPDATE todo_items
SET status = 'COMPLETED', completed_at = #{completedAt}, version = version + 1, updated_at = #{completedAt}
WHERE id = #{id} AND user_id = #{userId} AND version = #{version} AND status = 'PENDING' AND deleted_at IS NULL

mapper.insert:
INSERT INTO task_events (id, todo_id, event_type, payload, occurred_at)
SELECT #{id}, t.id, #{eventType}, jsonb_build_object(
    'title', #{title}, 'projectId', CAST(#{projectId} AS text),
    'fromStatus', CAST(#{fromStatus} AS text), 'toStatus', CAST(#{toStatus} AS text),
    'version', #{version}, 'result', #{result}
), #{occurredAt} FROM todo_items t WHERE t.id = #{todoId} AND t.user_id = #{userId}
